import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

const LIMIT = 32_000;
export function minimalEnvironment(names = [], supplied = process.env) {
  const keep = ['PATH', 'Path', 'SystemRoot', 'WINDIR', 'COMSPEC', 'PATHEXT', 'TEMP', 'TMP', 'HOME', 'USERPROFILE', 'LANG', 'LC_ALL'];
  return Object.fromEntries([...new Set([...keep, ...names])].filter(k => supplied[k] !== undefined).map(k => [k, supplied[k]]));
}

function executable(spec, cwd, env) {
  let command = spec.command;
  let args = spec.args ?? [];
  if (process.platform === 'win32' && /^(pnpm|pnpm\.cmd)$/i.test(command)) {
    const candidates = [];
    try {
      const require = createRequire(path.join(cwd, 'package.json'));
      candidates.push(require.resolve('pnpm/bin/pnpm.cjs'));
    } catch {}
    for (const directory of String(env.PATH ?? env.Path ?? '').split(path.delimiter)) {
      candidates.push(path.join(directory, 'node_modules', 'pnpm', 'bin', 'pnpm.cjs'));
      candidates.push(path.join(directory, 'pnpm.cjs'));
    }
    const entry = candidates.find(existsSync);
    if (!entry) throw new Error('Cannot resolve pnpm JavaScript entry; configure command as node with the pnpm.cjs path.');
    command = process.execPath;
    args = [entry, ...args];
  }
  if (process.platform === 'win32' && /\.(cmd|bat)$/i.test(command)) throw new Error('Shell shims are unsupported; configure their JavaScript entry.');
  return { command, args };
}

/** Array-only subprocess API. IPC is reserved for the hook adapter. */
export async function runCommand(spec, { cwd = process.cwd(), env = process.env, signal, onOutput, onSpawn } = {}) {
  if (!spec || typeof spec.command !== 'string' || !Array.isArray(spec.args ?? []) || !(spec.args ?? []).every(a => typeof a === 'string')) throw new Error('Command requires a program and string argument array.');
  const timeoutMs = spec.timeoutMs ?? 30_000;
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new Error('timeoutMs must be positive.');
  const startedAt = new Date().toISOString();
  if (signal?.aborted) return { status: 'cancelled', exitCode: null, signal: null, stdout: '', stderr: '', processStopped: true, startedAt, finishedAt: startedAt };
  const launch = executable(spec, cwd, env);
  return new Promise(resolve => {
    let stdout = '', stderr = '', reason = null, settled = false, killTimer, message, termination = null;
    const child = spawn(launch.command, launch.args, { cwd, env, shell: false, detached: process.platform !== 'win32', stdio: spec.ipc ? ['pipe', 'pipe', 'pipe', 'ipc'] : ['pipe', 'pipe', 'pipe'] });
    const capture = (stream, data) => {
      const text = String(data);
      if (stream === 'stdout') stdout = (stdout + text).slice(-LIMIT);
      else stderr = (stderr + text).slice(-LIMIT);
      onOutput?.(stream, text);
    };
    child.stdout.on('data', d => capture('stdout', d));
    child.stderr.on('data', d => capture('stderr', d));
    child.on('spawn', () => onSpawn?.(child.pid));
    child.on('message', value => { if (value?.type === 'result') message = value; });
    const killTree = force => {
      if (!child.pid) return;
      if (process.platform === 'win32') {
        return new Promise(done => {
          const killer = spawn('taskkill.exe', ['/PID', String(child.pid), '/T', ...(force ? ['/F'] : [])], { shell: false, windowsHide: true, stdio: 'ignore' });
          killer.on('error', () => done(false));
          killer.on('close', code => done(code === 0));
        });
      } else {
        try { process.kill(-child.pid, force ? 'SIGKILL' : 'SIGTERM'); return true; } catch (error) { return error.code === 'ESRCH'; }
      }
    };
    const stop = why => {
      if (reason || settled) return;
      reason = why;
      if (child.connected) child.send({ type: 'abort', reason: why }, () => {});
      // Give the handler's AbortSignal a brief opportunity to cancel its requests.
      killTimer = setTimeout(() => { termination = Promise.resolve(killTree(true)); }, 100);
    };
    const abort = () => stop('cancelled');
    signal?.addEventListener('abort', abort, { once: true });
    const timer = setTimeout(() => stop('timeout'), timeoutMs);
    const finish = async (code, terminationSignal) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      // Kill remaining descendants even if the parent exits during graceful cancellation.
      let processStopped = true;
      if (reason) {
        processStopped = await (termination ?? Promise.resolve(killTree(true)));
        if (processStopped && child.pid && process.platform !== 'win32') {
          processStopped = false;
          for (let attempt = 0; attempt < 50; attempt++) {
            try { process.kill(-child.pid, 0); }
            catch (error) { processStopped = error.code === 'ESRCH'; break; }
            await new Promise(done => setTimeout(done, 20));
          }
        }
      }
      else if (child.pid && process.platform !== 'win32') {
        try { process.kill(-child.pid, 0); processStopped = false; } catch (error) { processStopped = error.code === 'ESRCH'; }
      }
      clearTimeout(killTimer);
      signal?.removeEventListener('abort', abort);
      resolve({ status: !processStopped ? 'unknown' : reason ?? (code === 0 ? 'success' : 'failed'), processStopped, exitCode: code, signal: terminationSignal, stdout, stderr, startedAt, finishedAt: new Date().toISOString(), ...(message ? { message } : {}) });
    };
    child.on('error', error => { stderr = error.message; finish(null, null); });
    child.on('close', finish);
    if (spec.ipc) child.on('spawn', () => child.send(spec.message, error => { if (error) stop('failed'); }));
    if (spec.input !== undefined) child.stdin.end(String(spec.input)); else child.stdin.end();
  });
}

source.profile.mjs:
/** Portable cadence profiles. No harness-specific execution lives here. */
export const DEFAULT_PROFILE = {
  schemaVersion: 1, name: 'delivery-cadence', mode: 'standalone',
  iterationMinutes: 60, reviewEvery: 1,
  publication: { mode: 'manual', every: 2 },
  pipeline: { workAheadLimit: 1, maxInFlightReleases: 1, maxPendingReleases: 1 },
  budgets: { maxIterations: null, maxRunMinutes: null },
  checkpoints: [], binding: {},
  team: { maxImplementers: 3, maxBuildWriters: 1 },
  optimization: { mode: 'recommend', minimumSamples: 3,
    bounds: { iterationMinutes: [60, 120], publicationEvery: [1, 3], maxImplementers: [1, 3] } }
};

export function mergeProfile(base, patch) {
  const result = { ...base, ...patch };
  for (const key of ['publication', 'pipeline', 'budgets', 'team', 'binding', 'optimization']) {
    result[key] = { ...base[key], ...patch[key] };
  }
  result.optimization.bounds = { ...base.optimization.bounds, ...patch.optimization?.bounds };
  return validateProfile(result);
}

export function validateProfile(profile) {
  const fail = (message) => { throw new Error(`Invalid cadence profile: ${message}`); };
  if (profile.schemaVersion !== 1) fail('schemaVersion must be 1');
  if (!['standalone', 'kbd', 'goal'].includes(profile.mode)) fail('unknown execution mode');
  if (typeof profile.name !== 'string' || !profile.name.trim()) fail('name is required');
  if (!Number.isFinite(profile.iterationMinutes) || profile.iterationMinutes <= 0) fail('iterationMinutes must be positive');
  if (!Number.isInteger(profile.reviewEvery) || profile.reviewEvery < 0) fail('reviewEvery must be a nonnegative integer');
  if (!['manual', 'every', 'count', 'interval', 'either'].includes(profile.publication.mode)) fail('publication.mode must be manual, count, interval or either (every is the legacy count alias)');
  if (['interval', 'either'].includes(profile.publication.mode)) {
    if (!Number.isFinite(profile.publication.intervalMinutes) || profile.publication.intervalMinutes <= 0) fail('publication.intervalMinutes must be positive');
    if (typeof profile.publication.anchorUtc !== 'string' || !profile.publication.anchorUtc.endsWith('Z') || !Number.isFinite(Date.parse(profile.publication.anchorUtc))) fail('publication.anchorUtc needs an explicit UTC timestamp');
  }
  for (const name of ['workAheadLimit', 'maxInFlightReleases', 'maxPendingReleases']) {
    if ((profile.pipeline?.[name] ?? 1) !== 1) fail(`pipeline.${name} is bounded to one in this version`);
  }
  if (!Number.isInteger(profile.publication.every) || profile.publication.every < 1) fail('publication.every must be positive');
  for (const [key, value] of Object.entries(profile.budgets)) {
    if (value !== null && (!Number.isFinite(value) || value <= 0)) fail(`${key} must be positive or null`);
  }
  if (profile.budgets.maxIterations !== null && !Number.isInteger(profile.budgets.maxIterations)) fail('maxIterations must be an integer');
  if (!Array.isArray(profile.checkpoints)) fail('checkpoints must be an array');
  const seen = new Set();
  for (const step of profile.checkpoints) {
    if (!step.id || seen.has(step.id)) fail('checkpoint IDs must be present and unique');
    seen.add(step.id);
    if (!['build', 'run'].includes(step.kind)) fail('checkpoint kind must be build or run');
    if (typeof step.command !== 'string' || !step.command) fail(`${step.id} needs a command`);
    if (!Array.isArray(step.args) || step.args.some((arg) => typeof arg !== 'string')) fail(`${step.id} needs a string argument array`);
    if (typeof step.cwd !== 'string' || !step.cwd) fail(`${step.id} needs an explicit working directory`);
    if (step.required !== undefined && typeof step.required !== 'boolean') fail(`${step.id}.required must be boolean`);
    if (step.timeoutMs !== undefined && (!Number.isFinite(step.timeoutMs) || step.timeoutMs <= 0)) fail(`${step.id}.timeoutMs must be positive`);
    if (step.secretEnv !== undefined && (!Array.isArray(step.secretEnv) || step.secretEnv.some((key) => typeof key !== 'string'))) fail(`${step.id}.secretEnv must contain environment variable names`);
  }
  if (!Number.isInteger(profile.team.maxImplementers) || profile.team.maxImplementers < 1) fail('team.maxImplementers must be positive');
  if (profile.team.maxBuildWriters !== 1) fail('one shared build writer is required');
  if (!['recommend', 'automatic', 'off'].includes(profile.optimization.mode)) fail('unknown optimization mode');
  if (!Number.isInteger(profile.optimization.minimumSamples) || profile.optimization.minimumSamples < 3) fail('optimization needs at least three samples');
  for (const [key, range] of Object.entries(profile.optimization.bounds)) {
    if (!Array.isArray(range) || range.length !== 2 || !range.every(Number.isFinite) || range[0] <= 0 || range[0] > range[1]) fail(`invalid bounds for ${key}`);
  }
  return profile;
}

export function normalizedScope(scope = {}) {
  const result = {};
  for (const key of ['tasks', 'changes', 'phases', 'outcomes']) {
    const values = scope[key] ?? [];
    if (!Array.isArray(values) || values.some((value) => typeof value !== 'string')) throw new Error(`scope.${key} must contain string IDs`);
    result[key] = [...new Set(values)];
  }
  result.deliveryClass = typeof scope.deliveryClass === 'string' && scope.deliveryClass.trim() ? scope.deliveryClass : 'unclassified';
  result.owners = Array.isArray(scope.owners) ? structuredClone(scope.owners) : [];
  for (const key of ['authorityRefs', 'canonicalScopeRefs', 'childRefs']) {
    if (scope[key] !== undefined) {
      if (!Array.isArray(scope[key]) || scope[key].some(ref => typeof ref !== 'string' || !ref.trim())) throw new Error(`scope.${key} must contain reference strings`);
      result[key] = [...new Set(scope[key])];
    }
  }
  if (!result.outcomes.length) throw new Error('An independently usable outcome must be named in scope.outcomes');
  return result;
}

export function budgetReason(state, now = Date.now()) {
  const { budgets } = state.profile;
  if (budgets.maxRunMinutes && now >= Date.parse(state.startedAt) + budgets.maxRunMinutes * 60_000) return 'Run time budget exhausted';
  if (!state.activeIterationId && budgets.maxIterations && state.iterations.length >= budgets.maxIterations) return 'Iteration budget exhausted';
  return null;
}

